import type {TagProps} from '@smart/react-components';
import {Flex, Markdown, Tag} from '@smart/react-components';
import React from 'react';
import type {BadgeFootnotes} from '../../../bff/app-model/create-app-model';
import type {Badge, BadgeTypes} from '../../../bff/types';
import styles from './index.module.scss';

export type PromoBadgeProps = {
  badges?: Badge[];
  footnotes?: BadgeFootnotes;
};

export const PromoBadge = ({badges, footnotes}: PromoBadgeProps) => {
  const variants: Record<BadgeTypes, TagProps['variant']> = {
    PRIMARY: `primary`,
    GHOST: `inverted`,
    GRAY: `grey`,
    LIME: `lime`,
  };

  return (
    <>
      {badges && badges.length > 0 && (
        <Flex
          direction="row"
          gap={100}
          wrap="wrap"
          className={styles[`tag-container`]}
        >
          {badges.map((badge) => (
            <Tag key={badge.code} variant={variants[badge.type]}>
              <Markdown>{badge.description ?? (badge.name as string)}</Markdown>
              {footnotes?.[`badge/${badge.code}`] && (
                <sup className={styles[`footnotes`]}>
                  {footnotes?.[`badge/${badge.code}`]}
                </sup>
              )}
            </Tag>
          ))}
        </Flex>
      )}
    </>
  );
};

